import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`str-market-finder`,heroTitle:`Find your next short term rental market in minutes`,heroSubtitle:`Perplexity Computer analyzes market demand, comparable listings, seasonality, and operating assumptions to surface stronger short-term rental opportunities.`,inputUrlCta:`Find my market`,inputUrlPlaceholder:`e.g. a target city, listing, or market page`,inputUrlPrefill:`Use {url} as the starting market, city, or short-term rental listing context. Build a complete short-term rental market finder report. (1) Analyze demand, seasonality, local attractions, comparable listings, nightly rates, and occupancy signals. (2) Estimate operating costs, cleaning, management, taxes, insurance, and furnishing assumptions. (3) Compare nearby neighborhoods or alternative markets with upside and risk notes. (4) Identify regulatory, competition, and seasonality risks. (5) Deliver a ranked market recommendation with expected revenue drivers, due diligence questions, and next steps.`,heroOverlaySteps:[`Analyzing demand, seasonality, comparable listings, and nightly-rate signals`,`Estimating operating costs, management needs, taxes, and furnishing assumptions`,`Comparing nearby markets and neighborhoods for upside and risk`,`Ranked short-term rental market report with next steps, ready to review`],generatingSteps:[`Visiting {url} to understand the target market, listing, or city context`,`Designing an agent to compare demand, seasonality, pricing, and competition`,`Configuring underwriting logic for costs, occupancy, regulation, and market risk`,`Preparing a ranked short-term rental market report with due diligence next steps`],featureSectionTitle:`From market idea to investable short-term rental thesis`,featureCardTitles:[`Connects to your hosting research stack`,`Outputs you can underwrite`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Listing pages, spreadsheets, maps, docs, and planning tools stay connected so research and underwriting move together.`,`Comparable listings. Occupancy signals. Cost assumptions. Regulation risks. Computer gives you a market report that is ready for deeper diligence.`],capabilitySectionTitle:`Your STR market analyst, on autopilot`,capabilitySectionSubtitle:`Paste a market or listing, step away, and come back to a ranked opportunity report.`,capabilityCards:[{title:`Market Demand Analysis`,description:`Computer can analyze seasonality, local demand drivers, attractions, comparable listings, nightly rates, and occupancy signals.`},{title:`Operating Cost Model`,description:`Computer can estimate cleaning, management, taxes, insurance, furnishings, maintenance, and other assumptions that shape returns.`},{title:`Neighborhood Comparison`,description:`Computer can compare nearby neighborhoods or alternative markets to show where demand, pricing, and competition look strongest.`},{title:`Connect Your Tools`,description:`Computer can organize findings across listing pages, spreadsheets, maps, docs, and planning tools so underwriting is easier to review.`},{title:`Remember Your Criteria`,description:`Computer can remember your budget, target cash flow, preferred property type, and risk tolerance across future market searches.`},{title:`Risk Watchlist`,description:`Computer can flag regulation, seasonality, competition, and operating-risk questions that need answers before you move forward.`}]});export{t as default};
